/* API base. Resolution order: an explicit window.RAW_SWITCH_API (or
   <meta name="raw-switch-api">) wins; then same-origin when the dashboard is
   served by the API itself on port 8000; then the API on the same host (local
   dev served from another port); otherwise the production platform. */
const AUTH_API=(()=>{
  const meta=document.querySelector('meta[name="raw-switch-api"]');
  const override=window.RAW_SWITCH_API||(meta&&meta.content);
  if(override)return String(override).replace(/\/+$/,'');
  const host=location.hostname;
  const isLocal=location.protocol==='file:'||host==='localhost'||host==='127.0.0.1'||/^10\./.test(host)||/^192\.168\./.test(host)||/^172\.(1[6-9]|2\d|3[01])\./.test(host);
  if(isLocal)return location.port==='8000'?location.origin:`http://${host||'127.0.0.1'}:8000`;
  return 'http://45.159.228.52:8000';
})();
async function authRequest(path,options={}){const response=await fetch(`${AUTH_API}${path}`,{headers:{'Content-Type':'application/json',...(options.headers||{})},...options});if(!response.ok){let detail='Authentication service request failed';try{detail=(await response.json()).detail||detail}catch{}throw new Error(detail)}return response.json()}
