async function syncUsersFromServer(){try{const cachedUsers=users.map(user=>({...user})),remoteUsers=await authRequest('/auth/users'),remoteEmails=new Set(remoteUsers.map(user=>user.email.toLowerCase()));for(const user of cachedUsers){if(user.password&&user.email&&!remoteEmails.has(user.email.toLowerCase())){try{const imported=await authRequest('/auth/users',{method:'POST',body:JSON.stringify({name:user.name,email:user.email,password:user.password,role:user.role,status:user.status,accountRole:user.accountRole,permissions:user.permissions,customerName:customers.find(customer=>customer.adminEmail===user.email)?.name||null})});remoteUsers.push(imported);remoteEmails.add(imported.email.toLowerCase())}catch(error){console.warn(`Unable to migrate cached account ${user.email}`,error)}}}users.splice(0,users.length,...remoteUsers.map(user=>{const cached=cachedUsers.find(item=>item.email.toLowerCase()===user.email.toLowerCase());return{...user,password:cached?.password,avatar:user.name.split(' ').map(n=>n[0]).join('').toUpperCase().slice(0,2)}}));persistWorkspaceData();renderUsers()}catch(error){console.warn('Shared authentication service unavailable; using local account cache',error)}}
