function renderBrandingPanel(){const settings=document.querySelector('#settings');if(!settings||document.querySelector('#brandingCard'))return;const card=document.createElement('article');card.id='brandingCard';card.className='card branding-card';card.innerHTML=`<div class="card-heading"><div><h2>Company branding</h2><p>Customize the name, logo and colors shown across the workspace.</p></div><span class="badge active">Admin only</span></div><form id="brandingForm"><div class="form-grid"><label>Company name<input name="name" required maxlength="60"></label><label>Company logo <span class="optional">Optional</span><input name="logoFile" type="file" accept="image/png,image/jpeg,image/svg+xml,image/webp"><small class="field-help">Recommended: square image, up to 512 × 512 px.</small></label><label>Primary color<input name="primary" type="color"></label><label>Navigation color<input name="accent" type="color"></label></div><div class="branding-preview"><span class="brand-mark"><i data-lucide="orbit"></i><img id="brandingPreviewLogo" alt=""></span><strong id="brandingPreviewName"></strong></div><div class="branding-actions"><button type="button" class="btn btn-secondary" id="removeBrandLogo"><i data-lucide="trash-2"></i>Remove logo</button><button type="submit" class="btn btn-primary"><i data-lucide="check"></i>Save branding</button></div></form>`;settings.appendChild(card);const form=card.querySelector('#brandingForm');form.name.value=companyBranding.name;form.primary.value=companyBranding.primary;form.accent.value=companyBranding.accent;form.dataset.logo=companyBranding.logo;const updatePreview=()=>{card.querySelector('#brandingPreviewName').textContent=form.name.value||'Company name';const image=card.querySelector('#brandingPreviewLogo');image.src=form.dataset.logo||'';image.hidden=!form.dataset.logo};form.addEventListener('input',updatePreview);form.logoFile.addEventListener('change',()=>{const file=form.logoFile.files[0];if(!file)return;if(!file.type.startsWith('image/')){toast('Please choose an image file','error');form.logoFile.value='';return}const reader=new FileReader();reader.onload=()=>{form.dataset.logo=reader.result;updatePreview()};reader.onerror=()=>toast('Logo could not be read','error');reader.readAsDataURL(file)});card.querySelector('#removeBrandLogo').addEventListener('click',()=>{form.dataset.logo='';form.logoFile.value='';updatePreview();toast('Logo removed. Save branding to apply it')});form.addEventListener('submit',e=>{e.preventDefault();if(!currentUser||currentUser.role!=='Administrator'){toast('Only administrators can update company branding','error');return}const data=new FormData(form);companyBranding={name:data.get('name').trim(),logo:form.dataset.logo||'',primary:data.get('primary'),accent:data.get('accent')};localStorage.setItem('companyBranding',JSON.stringify(companyBranding));applyCompanyBranding();updatePreview();icons();toast('Company branding saved')});updatePreview();icons()}
