async function loadSystemHealth(){if(!currentUser||currentUser.role!=='Administrator')return;const panel=document.querySelector('#systemHealthCard');if(!panel)return;panel.querySelector('[data-health-refresh]').disabled=true;try{const health=await authRequest('/system/health');panel.querySelector('[data-health-status]').textContent=health.status==='online'?'Online':'Degraded';panel.querySelector('[data-health-status]').className=`badge ${health.status==='online'?'active':'suspended'}`;panel.querySelector('[data-health-checked]').textContent=`Checked ${new Date(health.checkedAt).toLocaleString()}`;panel.querySelector('[data-health-metrics]').innerHTML=Object.entries(health.counts).map(([key,value])=>`<div class="tech-stat"><span>${key.replace(/[A-Z]/g,letter=>' '+letter).replace(/^./,letter=>letter.toUpperCase())}</span><strong>${value}</strong></div>`).join('');panel.querySelector('[data-health-events]').innerHTML=health.recentEvents.length?health.recentEvents.map(event=>`<div class="stack-row"><div><strong>${event.status} · ${event.network}</strong><small>${event.device} · ${event.iccid} · ${event.timestamp?new Date(event.timestamp).toLocaleString():'Unknown time'}</small></div><span class="muted">${event.latencyMs} ms</span></div>`).join(''):'<p class="muted">No network events recorded yet.</p>'}catch(error){panel.querySelector('[data-health-status]').textContent='Unavailable';panel.querySelector('[data-health-status]').className='badge suspended';panel.querySelector('[data-health-events]').innerHTML='<p class="muted">System health could not be loaded. Check the backend service.</p>';toast(error.message||'Unable to load system health','error')}finally{panel.querySelector('[data-health-refresh]').disabled=false}}
