function renderSystemHealthPanel(){const settings=document.querySelector('#settings');if(!settings||document.querySelector('#systemHealthCard'))return;const panel=document.createElement('article');panel.id='systemHealthCard';panel.className='card';panel.innerHTML=`<div class="card-heading"><div><h2>Backend service health</h2><p>Safe runtime visibility into the SIM API and database. Credentials and operating-system logs are not exposed here.</p></div><span class="badge active" data-health-status>Checking</span></div><div class="stat-foot"><span data-health-checked>Not checked</span><button class="btn btn-secondary btn-small" data-health-refresh>Refresh</button></div><div class="tech-stats" data-health-metrics></div><h3>Recent network events</h3><div class="stack-list" data-health-events><p class="muted">Loading backend activity...</p></div>`;settings.appendChild(panel);panel.querySelector('[data-health-refresh]').addEventListener('click',loadSystemHealth);loadSystemHealth();icons()}
