function renderAnalytics(){const section=document.querySelector('#analytics');if(!section)return;const inventory=liveInventory||[];const totalUsage=inventory.reduce((sum,s)=>sum+(Number(s.used)||0),0),active=inventory.filter(s=>String(s.status).toLowerCase()==='active').length,total=inventory.length,metricCards=section.querySelectorAll('.stats-grid .stat-card');if(metricCards.length>=4){metricCards[0].querySelector('.stat-value').innerHTML=(totalUsage/30).toFixed(1)+' <small>GB</small>';metricCards[0].querySelector('.trend').textContent='Live inventory usage';metricCards[1].querySelector('.stat-value').innerHTML=(total?((active/total)*100).toFixed(2):'0.00')+'<small>%</small>';metricCards[1].querySelector('.muted').textContent=active+' of '+total+' SIMs active';metricCards[2].querySelector('.stat-value').innerHTML=(active?totalUsage/active:0).toFixed(1)+' <small>GB/SIM</small>';metricCards[2].querySelector('.trend').textContent='Calculated from live usage';metricCards[3].querySelector('.stat-value').textContent='$'+(active*1.51).toFixed(0);metricCards[3].querySelector('.muted').textContent='Calculated from active SIMs'}const groups=[['type',section.querySelectorAll('.bar-analytics')[0]],['networkTech',section.querySelectorAll('.bar-analytics')[1]]];groups.forEach(([key,container])=>{if(!container)return;const values={};inventory.forEach(sim=>{const label=sim[key]||'Unknown';values[label]=(values[label]||0)+(Number(sim.used)||0)});const max=Math.max(...Object.values(values),1);container.innerHTML=Object.entries(values).map(([label,value])=>`<div><span>${label} <b>${value.toFixed(1)} GB</b></span><div><i style="width:${(value/max*100).toFixed(0)}%;background:#ff9800"></i></div></div>`).join('')||'<p class="muted">No inventory data available.</p>'})}
