// it through this helper so the open state can never drift from the DOM.
function toggleMenu(open){const sidebar=document.querySelector('#sidebar');if(!sidebar)return;const scrim=document.querySelector('#sidebarScrim'),button=document.querySelector('#menuBtn');const next=open===undefined?!sidebar.classList.contains('open'):!!open;sidebar.classList.toggle('open',next);if(scrim)scrim.classList.toggle('open',next);if(button)button.setAttribute('aria-expanded',next?'true':'false');document.body.classList.toggle('nav-open',next)}
function navigate(view){syncNavGroup(view);if(view!=='login'&&!checkAuth())return;document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===view));document.querySelectorAll('.nav-item[data-view]').forEach(n=>n.classList.toggle('active',n.dataset.view===view));toggleMenu(false);document.querySelector('#authOverlay').classList.remove('open');window.scrollTo({top:0,behavior:'smooth'});if(view==='users')renderUsers();if(view==='portal')renderPortal();if(view==='dashboard'&&currentUser){document.querySelector('#dashboard h1').innerHTML='Good morning, '+currentUser.name.split(' ')[0]+' <span>👋</span>'}if(view==='marketplace')loadMarketplaceData()}
let liveInventory=null;
function mapInventoryDevice(device){const status=String(device.status||'provisioned').toLowerCase();return{id:device.id,device:device.device||'Unnamed device',iccid:device.iccid,type:device.type||'IoT SIM',networkTech:device.networkTech||'Unknown',network:device.network||'Auto select',location:device.location||'Global',used:Number(device.usageMb||0)/1024,allocated:Number(device.dataLimitMb||0)/1024,cap:true,roamingEnabled:device.roamingEnabled!==false,status:status==='active'?'Active':status.charAt(0).toUpperCase()+status.slice(1),customer:device.customer||'Unassigned'}};
async function loadActualInventory(){try{const response=await fetch(`${AUTH_API}/inventory?refresh=${Date.now()}`);if(!response.ok)throw new Error(`Inventory request failed (${response.status})`);liveInventory=(await response.json()).map(mapInventoryDevice);sims.splice(0,sims.length,...liveInventory.map(s=>({...s,usage:`${Number(s.used||0).toFixed(2)} GB`,seen:'Live'})));renderDashboardStats();renderSims();renderSimManagementStats();renderRegions();renderCustomers();renderAnalytics();if(currentUser?.role==='Customer')renderPortal();return liveInventory}catch(error){renderDashboardStats();renderSims();renderSimManagementStats();renderRegions();renderCustomers();renderAnalytics();console.warn('Unable to load live customer inventory; showing empty live state',error);return null}}
async function refreshAnalytics(){const inventory=await loadActualInventory();if(inventory!==null)renderAnalytics()}
async function syncCustomerAccounts(){if(currentUser?.role!=='Administrator')return;for(const customer of customers){const user=users.find(item=>item.email?.toLowerCase()===customer.adminEmail?.toLowerCase());if(!user||!customer.adminEmail)continue;try{const updated=await authRequest(`/auth/users/${user.id}`,{method:'PATCH',body:JSON.stringify({customerName:customer.name,packageGb:Number(customer.packageGb)||0,usedGb:Number(customer.usedGb)||0,accountBalance:customerBalance(customer)})});Object.assign(user,updated)}catch(error){console.warn(`Unable to sync ${customer.name} account`,error)}}persistWorkspaceData()}
async function saveCustomerAccount(customer){const user=users.find(item=>item.email?.toLowerCase()===customer?.adminEmail?.toLowerCase())||(currentUser?.role==='Customer'?currentUser:null);if(!user||!customer)return false;try{const updated=await authRequest(`/auth/users/${user.id}`,{method:'PATCH',body:JSON.stringify({customerName:customer.name,packageGb:Number(customer.packageGb)||0,usedGb:Number(customer.usedGb)||0,accountBalance:customerBalance(customer)})});Object.assign(user,updated);if(currentUser?.id===user.id)Object.assign(currentUser,updated);persistWorkspaceData();return true}catch(error){console.warn(`Unable to save ${customer.name} account`,error);toast('Account change could not be saved to the shared server','error');return false}}
async function refreshCustomerAccounts(){try{const remoteUsers=await authRequest('/auth/users'),remoteCustomers=remoteUsers.filter(user=>user.role==='Customer'&&user.customerName);customers.splice(0,customers.length,...remoteCustomers.map(remote=>{const existing=customers.find(item=>item.name===remote.customerName);const initials=remote.customerName.split(/\s+/).map(part=>part[0]).join('').slice(0,2).toUpperCase();return{...existing,name:remote.customerName,industry:existing?.industry||'Customer account',count:0,usage:'0 GB',packageGb:Number(remote.packageGb)||0,usedGb:Number(remote.usedGb)||0,accountBalance:Number.isFinite(Number(remote.accountBalance))?Number(remote.accountBalance):248.5,color:existing?.color||'purple',initials,adminEmail:remote.email,status:remote.status}}));for(const remote of remoteUsers){const localUser=users.find(user=>user.id===remote.id||user.email?.toLowerCase()===remote.email?.toLowerCase());if(localUser)Object.assign(localUser,remote)}persistWorkspaceData();renderCustomers();renderProvisionCustomerOptions();if(currentUser?.role==='Customer'){currentUser=users.find(user=>user.id===currentUser.id)||currentUser;applyCustomerAccount();renderPortal()}}catch(error){console.warn('Unable to refresh shared customer accounts',error)}}
async function updateLiveDevice(sim,payload){if(!sim?.iccid)return false;try{const updated=await authRequest(`/inventory/${sim.iccid}`,{method:'PATCH',body:JSON.stringify(payload)});const mapped=mapInventoryDevice(updated);liveInventory=(liveInventory||[]).map(item=>item.iccid===sim.iccid?mapped:item);return true}catch(error){console.warn(`Unable to save ${sim.iccid}`,error);toast('SIM change could not be saved to the shared server','error');return false}}
async function syncAdminInventory(){if(currentUser?.role!=='Administrator')return;try{const existing=new Set((liveInventory||[]).map(device=>device.iccid));for(const sim of sims){if(existing.has(sim.iccid)||!/^\d{15,22}$/.test(sim.iccid))continue;const created=await authRequest('/inventory',{method:'POST',body:JSON.stringify({device:sim.device,iccid:sim.iccid,type:sim.type,networkTech:sim.networkTech,customer:sim.customer,region:sim.location||'Global',dataPlan:'500 MB / month',roamingEnabled:true})});liveInventory=[...(liveInventory||[]),mapInventoryDevice(created)];existing.add(sim.iccid)}}catch(error){console.warn('Unable to synchronize administrator inventory',error)}}
async function login(identifier,password){try{const remote=await authRequest('/auth/login',{method:'POST',body:JSON.stringify({identifier,password})});const user={...remote,avatar:remote.name.split(' ').map(n=>n[0]).join('').toUpperCase().slice(0,2)};const index=users.findIndex(u=>u.id===user.id);if(index>=0)users[index]={...users[index],...user};else users.push(user);persistWorkspaceData();currentUser=user;isAuthenticated=true;document.body.classList.toggle('customer-mode',user.role==='Customer');document.querySelector('#userBtn').textContent=user.avatar;document.querySelector('.sidebar-profile .avatar').firstChild.textContent=user.avatar;document.querySelector('#sidebar-profile-name').textContent=user.name;document.querySelector('#sidebar-profile-role').textContent=user.accountRole||user.role;applyCustomerPermissions();document.querySelector('#userDropdown').style.display='inline-block';await loadActualInventory();await syncAdminInventory();await refreshCustomerAccounts();return true}catch(error){const value=String(identifier||'').trim().toLowerCase(),user=users.find(u=>(u.email||'').toLowerCase()===value||(u.name||'').toLowerCase()===value);if(!user||user.password!==password||user.status!=='Active')return false;currentUser=user;isAuthenticated=true;document.body.classList.toggle('customer-mode',user.role==='Customer');applyCustomerPermissions();await loadActualInventory();await refreshCustomerAccounts();return true}}
function logout(){stopSystemHealthRefresh();persistWorkspaceData();currentUser=null;isAuthenticated=false;document.body.classList.remove('customer-mode');document.querySelector('#userBtn').textContent='AM';document.querySelector('.sidebar-profile .avatar').firstChild.textContent='AM';document.querySelector('#sidebar-profile-name').textContent='Alex Morgan';document.querySelector('#sidebar-profile-role').textContent='Administrator';document.querySelector('#userDropdown').style.display='none';document.querySelector('#authOverlay').classList.add('open');document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));toggleMenu(false);toast('Signed out')}
function renderUsers(){document.querySelector('#userCount').textContent=users.length;document.querySelector('#adminCount').textContent=users.filter(u=>u.role==='Administrator').length;document.querySelector('#userStdCount').textContent=users.filter(u=>u.role==='User').length;const q=document.querySelector('#userSearch').value.toLowerCase();const role=document.querySelector('#userRoleFilter').value;const filtered=users.filter(u=>(role==='All'||u.role===role)&&(u.name+' '+u.email).toLowerCase().includes(q));document.querySelector('#userBody').innerHTML=filtered.map(u=>`<tr><td><div class="device-cell"><span class="device-icon" style="background:#ffeeda;color:#e08200">${u.avatar}</span><div><strong>${u.name}</strong><small>#${u.id}</small></div></div></td><td>${u.email}</td><td><span class="badge ${u.role==='Administrator'?'purple-bg':''}">${u.role}</span></td><td><span class="badge ${u.status==='Active'?'active':u.status==='Inactive'?'inactive':'suspended'}">${u.status}</span></td><td>${u.lastLogin}</td><td><div style="display:flex;gap:6px"><button class="row-action" data-user="${u.id}" title="Edit"><i data-lucide="edit-2"></i></button><button class="row-action" data-user="${u.id}" title="${u.status==='Active'?'Suspend':'Activate'}"><i data-lucide="${u.status==='Active'?'pause':'play'}"></i></button><button class="row-action" data-user="${u.id}" title="Delete"><i data-lucide="trash-2"></i></button></div></td></tr>`).join('')||'<tr><td colspan="7" style="text-align:center;padding:35px">No users found.</td></tr>';icons()}
function renderRoles(){const list=document.querySelector('#roleList');if(!list)return;list.innerHTML=platformRoles.map(role=>`<div class="role-list-item"><div><strong>${role.name}</strong><small>${role.permissions.length} permissions</small></div><div class="permission-tags">${role.permissions.slice(0,4).map(p=>`<span>${permissionCatalog.find(x=>x[0]===p)?.[1]||p}</span>`).join('')}${role.permissions.length>4?`<span>+${role.permissions.length-4}</span>`:''}</div></div>`).join('');const roleSelect=document.querySelector('#userAccountRole');if(roleSelect)roleSelect.innerHTML=platformRoles.map(role=>`<option value="${role.name}">${role.name}</option>`).join('')}
function renderPermissionChecks(containerId,selected=[]){const container=document.querySelector('#'+containerId);if(!container)return;container.innerHTML=permissionCatalog.map(([value,label])=>`<label><input type="checkbox" name="permissions" value="${value}" ${selected.includes(value)?'checked':''}> ${label}</label>`).join('')}
function rolePermissions(name){return platformRoles.find(role=>role.name===name)?.permissions||[]}
function addUser(name,email,role,status,password,accountRole,permissions){const id=Math.max(...users.map(u=>u.id))+1;const avatar=name.split(' ').map(n=>n[0]).join('').toUpperCase().slice(0,2);users.push({id,name,email,role,status,lastLogin:'Never',avatar,password:password||'default123',accountRole,permissions});persistWorkspaceData();renderUsers();return users[users.length-1]}
async function updateUser(id,updates){const u=users.find(x=>x.id===id);if(!u)return false;try{const remote=await authRequest(`/auth/users/${id}`,{method:'PATCH',body:JSON.stringify(updates)});Object.assign(u,remote);u.avatar=u.name.split(' ').map(n=>n[0]).join('').toUpperCase().slice(0,2);if(currentUser?.id===id)Object.assign(currentUser,u);persistWorkspaceData();renderUsers();return true}catch(error){console.warn(`Unable to update user ${id} on the shared server`,error);toast(error.message||'User change could not be saved','error');return false}}
async function deleteUser(id){const user=users.find(item=>item.id===id);if(!user)return false;if(currentUser?.id===id){toast('You cannot delete the account currently signed in','error');return false}if(!window.confirm(`Delete ${user.name}'s account? This cannot be undone.`))return false;try{await authRequest(`/auth/users/${id}`,{method:'DELETE'});users.splice(users.findIndex(item=>item.id===id),1);persistWorkspaceData();renderUsers();toast(`${user.name} account deleted`);return true}catch(error){console.warn(`Unable to delete user ${id} on the shared server`,error);toast(error.message||'User account could not be deleted','error');return false}}

function navigate(view){syncNavGroup(view);if(view==='network-apis'&&(!currentUser||currentUser.role!=='Administrator')){toast('Only administrators can configure network APIs','error');return}if(currentUser&&currentUser.role==='Customer'){const need={'customer-dashboard':'dashboard','customer-reports':'reports','customer-team':'team','billing':'billing'}[view];if(!['portal','customer-dashboard','customer-reports','customer-team','billing'].includes(view)||(need&&!hasCustomerPermission(need))||(view==='portal'&&!['sims','data','billing'].some(hasCustomerPermission)))return;}document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===view));document.querySelectorAll('.nav-item[data-view]').forEach(n=>n.classList.toggle('active',n.dataset.view===view));toggleMenu(false);window.scrollTo({top:0,behavior:'smooth'});if(view==='portal')renderPortal();if(view==='analytics'){renderAnalytics();refreshAnalytics()}if(view==='settings'){renderSystemHealthPanel();loadSystemHealth();startSystemHealthRefresh()}else stopSystemHealthRefresh()}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-view]');if(nav)navigate(nav.dataset.view);const sim=e.target.closest('[data-sim]');if(sim){const item=sims[+sim.dataset.sim];item.status=item.status==='Active'?'Suspended':'Active';renderSims();renderActivity();renderSimManagementStats();toast(`${item.device} is now ${item.status.toLowerCase()}`)}const credentials=e.target.closest('[data-customer-credentials]');if(credentials){openCustomerCredentials(credentials.dataset.customerCredentials);return}const customer=e.target.closest('[data-customer]');if(customer){navigate('sims');document.querySelector('#simSearch').value=customer.dataset.customer;renderSims()}});
let toastTimer;function toast(message){const el=document.querySelector('#toast');el.querySelector('span').textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3000)}
const backdrop=document.querySelector('#modalBackdrop');function openModal(type='sim'){backdrop.classList.add('open');document.querySelectorAll('.user-admin-field').forEach(f=>f.hidden=type==='profile');document.querySelector('#teamMemberForm').hidden=type!=='team';document.querySelector('#roleForm').hidden=type!=='role';document.querySelector('#simForm').customer.disabled=!!currentUser&&currentUser.role==='Customer';if(currentUser&&currentUser.role==='Customer')document.querySelector('#simForm').customer.value='Trackfinity';document.querySelector('#simForm').hidden=type!=='sim';document.querySelector('#customerForm').hidden=type!=='customer';document.querySelector('#userForm').hidden=!['user','profile'].includes(type);if(type==='user'){renderRoles();renderPermissionChecks('userPermissionChecks',rolePermissions('User'));document.querySelector('#userAccountRole').value='User'}if(type==='role'){document.querySelector('#modalTitle').textContent='Add a role';document.querySelector('#modalSubtitle').textContent='Define a reusable set of workspace permissions.';renderPermissionChecks('rolePermissionChecks')}if(type==='profile'){if(!currentUser)return;document.querySelector('#userForm').hidden=false;document.querySelector('#modalTitle').textContent='My Profile';document.querySelector('#userForm').name.value=currentUser.name;document.querySelector('#userForm').email.value=currentUser.email;document.querySelector('#userForm').role.value=currentUser.role;document.querySelector('#userForm').status.value=currentUser.status;document.querySelector('#userForm').role.disabled=true;document.querySelector('#userForm').accountRole.disabled=true;document.querySelector('#userForm').password.value=''}else if(type!=='role'){document.querySelector('#modalTitle').textContent=type==='sim'?'Provision a new SIM':type==='customer'?'Add a new customer':'Add a new user';document.querySelector('#modalSubtitle').textContent=type==='sim'?'Add a new connected device to your fleet.':type==='customer'?'Create a customer profile and connect their fleet.':'Create a new platform user account.'}setTimeout(()=>document.querySelector(`#${type==='sim'?'simForm':type==='customer'?'customerForm':type==='role'?'roleForm':'userForm'} input`).focus(),100)}function closeModal(){backdrop.classList.remove('open')}
document.querySelectorAll('.add-sim').forEach(b=>b.addEventListener('click',()=>openModal()));document.querySelectorAll('[data-format-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-format-filter]').forEach(card=>card.classList.toggle('active',card===b));simFormatView=b.dataset.formatFilter;document.querySelector('#typeFilter').value='All';document.querySelector('#simSearch').value='';renderSims()}));document.querySelector('#addCustomer').addEventListener('click',()=>{if(!currentUser||currentUser.role!=='Administrator'){toast('Only administrators can add customers','error');return}openModal('customer')});document.querySelector('#closeModal').addEventListener('click',closeModal);document.querySelector('#cancelModal').addEventListener('click',closeModal);document.querySelectorAll('.cancel-modal').forEach(b=>b.addEventListener('click',closeModal));backdrop.addEventListener('click',e=>e.target===backdrop&&closeModal());document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();document.querySelector('#notificationPanel').classList.remove('open')}if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();document.querySelector('#globalSearch').focus()}});
document.querySelector('#simForm').addEventListener('submit',async e=>{e.preventDefault();const d=new FormData(e.target),customer=currentUser?.role==='Customer'?currentCustomer()?.name:d.get('customer'),payload={device:d.get('device'),iccid:d.get('iccid')||'894410'+String(Date.now()).slice(-13),type:d.get('type'),networkTech:d.get('networkTech'),customer,region:d.get('region'),dataPlan:d.get('plan'),roamingEnabled:d.get('roaming')==='on'};if(!customer){toast('Select a customer account from live backend data','error');return}try{await authRequest('/inventory',{method:'POST',body:JSON.stringify(payload)});await loadActualInventory();toast('SIM provisioned and loaded from the backend')}catch(error){toast(error.message||'SIM provisioning failed; no local placeholder was created','error');return}closeModal();e.target.reset();renderProvisionCustomerOptions();renderSims();renderPortal();navigate('sims')});
function parseBulkCsv(text){const lines=text.split(/\r?\n/).map(line=>line.trim()).filter(Boolean);if(lines.length<2)throw new Error('CSV must include a header row and at least one SIM row');const headers=lines.shift().split(',').map(value=>value.trim().toLowerCase());return lines.map(line=>{const values=line.split(',');const row={};headers.forEach((header,index)=>row[header]=String(values[index]||'').trim());return{device:row.device||row.devicename,iccid:row.iccid,type:row.type||row.simtype,networkTech:row.networktech||row.network_tech,customer:row.customer,region:row.region||row.location,dataPlan:row.dataplan||row.plan,roamingEnabled:!['false','no','0'].includes((row.roamingenabled||row.roaming||'true').toLowerCase())}})}
document.querySelector('#bulkTemplate')?.addEventListener('click',()=>{const rows=[['device','iccid','type','networkTech','customer','region','dataPlan','roamingEnabled'],['Replace with device name','8944100038201748921','eSIM (SGP.32)','4G','Trackfinity','Europe','1 GB / month','true'],['Replace with device name','8944100038201748855','UICC','NB-IoT','AgriSense','Africa','500 MB / month','true']];const csv=rows.map(row=>row.map(value=>`"${String(value).replaceAll('"','""')}"`).join(',')).join('\n');const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));link.download='sim-bulk-provisioning-template.csv';link.click();URL.revokeObjectURL(link.href);toast('Bulk provisioning template downloaded')});
document.querySelector('#bulkProvision')?.addEventListener('click',()=>{if(!currentUser||currentUser.role!=='Administrator'){toast('Only administrators can bulk provision SIMs','error');return}const input=document.createElement('input');input.type='file';input.accept='.csv,text/csv';input.onchange=()=>{const file=input.files?.[0];if(!file)return;const reader=new FileReader();reader.onerror=()=>toast('Unable to read the CSV file','error');reader.onload=async()=>{try{const items=parseBulkCsv(String(reader.result||''));const result=await authRequest('/inventory/bulk',{method:'POST',body:JSON.stringify({items})});const created=result.results.filter(item=>item.status==='created').map(item=>mapInventoryDevice(item.device));liveInventory=[...(liveInventory||[]),...created];await loadActualInventory();renderSims();renderSimManagementStats();toast(`${result.created} SIMs provisioned; ${result.failed} failed${result.failed?' — review the batch result':''}`,result.failed?'error':undefined)}catch(error){toast(error.message||'Bulk provisioning failed','error')}};reader.readAsText(file)};input.click()});
document.querySelector('#customerForm').addEventListener('submit',async e=>{e.preventDefault();if(!currentUser||currentUser.role!=='Administrator'){toast('Only administrators can add customers','error');return}const d=new FormData(e.target),name=d.get('company').trim(),email=d.get('email').trim().toLowerCase(),adminName=d.get('adminName').trim();if(users.some(u=>u.email.toLowerCase()===email)){toast('A user with this email already exists','error');return}try{const created=await authRequest('/auth/users',{method:'POST',body:JSON.stringify({name:adminName,email,password:d.get('password'),role:'Customer',status:'Active',accountRole:'Customer Admin',permissions:customerRolePermissions['Customer Admin'],customerName:name,packageGb:0,usedGb:0,accountBalance:248.5})});users.push({...created,password:d.get('password'),avatar:adminName.split(' ').map(x=>x[0]).join('').slice(0,2).toUpperCase()});customers.unshift({name,industry:d.get('industry'),count:+d.get('count'),usage:'0 GB',packageGb:0,usedGb:0,color:'purple',initials:name.split(' ').map(x=>x[0]).join('').slice(0,2).toUpperCase(),adminEmail:email});persistWorkspaceData();closeModal();e.target.reset();renderCustomers();renderUsers();toast(`${name} and its customer admin were created`)}catch(error){toast(error.message,'error')}});
['simSearch','statusFilter','typeFilter','techFilter'].forEach(id=>document.querySelector('#'+id).addEventListener(id==='simSearch'?'input':'change',renderSims));
document.querySelector('#globalSearch').addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.value.trim()){document.querySelector('#simSearch').value=e.target.value;renderSims();navigate('sims')}});
function reportInventory(){const inventory=liveInventory||[];if(currentUser?.role!=='Customer')return inventory;const customerName=currentUser.customerName||currentCustomer()?.name;return inventory.filter(item=>String(item.customer||'').toLowerCase()===String(customerName||'').toLowerCase())}
function saveReportHistory(name,rows){const history=JSON.parse(localStorage.getItem('nexoraReportHistory')||'[]');history.unshift({name,createdAt:new Date().toISOString(),count:rows.length});localStorage.setItem('nexoraReportHistory',JSON.stringify(history.slice(0,10)));renderReportHistory()}
function renderReportHistory(){const history=JSON.parse(localStorage.getItem('nexoraReportHistory')||'[]'),container=document.querySelector('#reports .report-history');if(!container||!history.length)return;container.querySelector('.card-heading p').textContent='Reports generated in this browser';container.querySelectorAll('.report-line').forEach(line=>line.remove());container.insertAdjacentHTML('beforeend',history.map(item=>`<div class="report-line"><span class="report-icon purple"><i data-lucide="file-text"></i></span><div><strong>${item.name}</strong><small>${new Date(item.createdAt).toLocaleString()} · ${item.count} records</small></div><span class="badge active">Saved</span></div>`).join(''));icons()}
function download(name='Fleet inventory'){const inventory=reportInventory(),rows=[['Device','ICCID','SIM Type','Customer','Network','Usage GB','Allocated GB','Status','Roaming enabled'],...inventory.map(s=>[s.device,s.iccid,s.type,s.customer,s.network,Number(s.used||0).toFixed(3),Number(s.allocated||0).toFixed(3),s.status,s.roamingEnabled!==false?'Yes':'No'])];const csv=rows.map(r=>r.map(v=>`"${String(v).replaceAll('"','""')}"`).join(',')).join('\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));const a=document.createElement('a');a.href=url;a.download=name.toLowerCase().replaceAll(' ','-')+'.csv';a.click();URL.revokeObjectURL(url);saveReportHistory(name,inventory);toast(`${name} downloaded and saved`)}
document.querySelectorAll('[data-report],.download-report').forEach(b=>b.addEventListener('click',()=>download(b.dataset.report||'Connectivity report')));document.querySelector('#exportOverview').addEventListener('click',()=>download('Fleet overview'));document.querySelector('#exportSims').addEventListener('click',()=>download('SIM inventory'));document.querySelector('#customReport').addEventListener('click',()=>download('Custom connectivity report'));
const roamingPolicyKey='nexoraRoamingPolicies';
