async function loadRoamingPolicies(){const local=JSON.parse(localStorage.getItem(roamingPolicyKey)||'{}');try{const saved=await authRequest('/roaming/policies');document.querySelectorAll('[data-policy]').forEach(control=>{control.checked=saved[control.dataset.policy]!==undefined?saved[control.dataset.policy]:control.checked});localStorage.setItem(roamingPolicyKey,JSON.stringify(saved))}catch(error){document.querySelectorAll('[data-policy]').forEach(control=>{if(local[control.dataset.policy]!==undefined)control.checked=local[control.dataset.policy]});console.warn('Unable to load roaming policies from server',error)}}
