const networkApiState={networks:[],euiccs:[],operations:[]};
async function loadNetworkApiData(){try{const [networks,euiccs,operations]=await Promise.all([authRequest('/telecom/networks'),authRequest('/euicc'),authRequest('/rsp/operations')]);networkApiState.networks=networks;networkApiState.euiccs=euiccs;networkApiState.operations=operations;renderNetworkApiData()}catch(error){toast(error.message||'Unable to load network API data','error')}}
function renderNetworkApiData(){const networkCount=document.querySelector('#networkApiCount'),euiccCount=document.querySelector('#euiccCount'),networkList=document.querySelector('#networkApiList'),euiccList=document.querySelector('#euiccList'),rspEid=document.querySelector('#rspEid'),rspNetwork=document.querySelector('#rspNetwork'),operationList=document.querySelector('#rspOperationList');if(!networkList)return;networkCount.textContent=`${networkApiState.networks.length} configured`;euiccCount.textContent=`${networkApiState.euiccs.length} registered`;networkList.innerHTML=networkApiState.networks.length?networkApiState.networks.map(n=>`<div class="stack-row"><div><strong>${n.name}</strong>${/^(https?:\/\/)?(127\.0\.0\.1|localhost|10\.|192\.168\.|172\.(1[6-9]|2[0-9]|3[01])\.)/i.test(n.apiBaseUrl||'')?'<span class="badge sandbox">Sandbox</span>':''}<small>${n.country} · ${n.apiBaseUrl}</small></div><div><button class="btn btn-secondary btn-small" data-network-test="${n.id}">Test API</button><button class="btn btn-secondary btn-small" data-network-attach="${n.id}">Connect SIM</button></div></div>`).join(''):'<p class="muted">No telecom networks configured.</p>';euiccList.innerHTML=networkApiState.euiccs.length?networkApiState.euiccs.map(e=>`<div class="stack-row"><div><strong>${e.eid}</strong><small>${e.smdpAddress||'No SM-DP+ address'} · ${e.status}</small></div></div>`).join(''):'<p class="muted">No eUICCs registered.</p>';rspEid.innerHTML='<option value="">Select an eUICC</option>'+networkApiState.euiccs.map(e=>`<option value="${e.eid}">${e.eid}</option>`).join('');rspNetwork.innerHTML='<option value="">Select a telecom network</option>'+networkApiState.networks.filter(n=>n.isActive).map(n=>`<option value="${n.id}">${n.name} · ${n.country}</option>`).join('');operationList.innerHTML=networkApiState.operations.length?networkApiState.operations.map(o=>`<div class="stack-row"><div><strong>${o.operation} · ${o.eid}</strong><small>${o.id} · ${o.status}${o.error?` · ${o.error}`:''}</small></div></div>`).join(''):'<p class="muted">No RSP operations submitted.</p>';icons()}
